  3	/**
  4	 * personas/plugins/ledger/index.js
  5	 *
  6	 * Factory function for the ledger persona build plugin.
  7	 *
  8	 * Ported from src/plugins/ledger/index.ts in persona-builder.
  9	 *
 10	 * ledgerPlugin(options) assembles the core modules from the ledger plugin
 11	 * package into a PersonaBuildPlugin-conformant object and returns it.
 12	 *
 13	 * Hooks implemented:
 14	 *   - onBuildContext  — injects roster_rendered and mcp_tools_table into
 15	 *                       the build context so templates can reference them.
 16	 *                       Also applies model assignment overrides from the
 17	 *                       model registry (assignments.json / local.json).
 18	 *   - onPostRender    — captures the rendered output per-persona so the
 19	 *                       onValidate hook can run the note_only guard against
 20	 *                       the real generated content.
 21	 *   - onValidate      — invokes validateRole (role against workflow manifest)
 22	 *                       and validateNoteOnlyGuard (ensures note_only tools
 23	 *                       are not present in the rendered output).
 24	 *   - frontmatterTemplates — registers the ledger-specific frontmatter templates
 25	 *                             for the vscode and claude-code targets.
 26	 *
 27	 * @example
 28	 * const { ledgerPlugin } = require('./plugins/ledger');
 29	 * const manifest = require('./shared/workflow-manifest.json');
 30	 *
 31	 * const plugin = ledgerPlugin({
 32	 *   manifestRoles: manifest.roles.map(r => r.name),
 33	 * });
 34	 */
