 36	const fs   = require('fs');
 37	const path = require('path');
 38	
 39	const { renderRoster }              = require('./roster-renderer');
 40	const { renderMcpToolsTable }       = require('./mcp-tools-renderer');
 41	const { validateRole, validateNoteOnlyGuard } = require('./role-validator');
 42	const { FRONTMATTER_LEDGER_VSCODE, FRONTMATTER_LEDGER_CC } = require('./frontmatter-templates');
 43	
 44	// ---------------------------------------------------------------------------
 45	// Model registry loader (loaded once per process, shared across plugin calls)
 46	// ---------------------------------------------------------------------------
 47	
 48	/**
 49	 * Absolute path to the model-registry directory.
 50	 * Resolved relative to this plugin file: personas/plugins/ledger/ → personas/model-registry/
 51	 */
 52	const MODEL_REGISTRY_DIR = path.join(__dirname, '..', '..', 'model-registry');
 53	
 54	/**
 55	 * Load the model registry from the model-registry directory.
 56	 *
 57	 * Reads `local.json` (falling back to `default.json`) to build the UUID → slug
 58	 * map and `cc_model` lookup, and reads `assignments.json` when present.
 59	 *
 60	 * Graceful: missing or malformed files produce empty maps / null assignments
 61	 * so that builds without a configured registry work unchanged (YAML-only fallback).
 62	 *
 63	 * @param {string} registryDir
 64	 * @returns {{ uuidToSlug: Map<string,string>, slugToEntry: Map<string,object>, assignments: object|null }}
 65	 */
 66	function loadModelRegistry(registryDir) {
 67	  const uuidToSlug  = new Map();
 68	  const slugToEntry = new Map();
 69	
 70	  // Prefer local.json; fall back to default.json
 71	  const localPath   = path.join(registryDir, 'local.json');
 72	  const defaultPath = path.join(registryDir, 'default.json');
 73	  const regPath     = fs.existsSync(localPath) ? localPath : defaultPath;
 74	
 75	  if (fs.existsSync(regPath)) {
 76	    try {
 77	      const entries = JSON.parse(fs.readFileSync(regPath, 'utf8'));
 78	      if (Array.isArray(entries)) {
 79	        for (const entry of entries) {
 80	          if (entry && typeof entry.id === 'string' && typeof entry.slug === 'string') {
 81	            uuidToSlug.set(entry.id, entry.slug);
 82	            slugToEntry.set(entry.slug, entry);
 83	          }
 84	        }
 85	      }
 86	    } catch (_e) {
 87	      // Malformed registry — fall back to YAML-only behavior silently
 88	    }
 89	  }
 90	
 91	  let assignments = null;
 92	  const assignmentsPath = path.join(registryDir, 'assignments.json');
 93	  if (fs.existsSync(assignmentsPath)) {
 94	    try {
 95	      const raw = JSON.parse(fs.readFileSync(assignmentsPath, 'utf8'));
 96	      if (raw && typeof raw === 'object') {
 97	        assignments = raw;
 98	      }
 99	    } catch (_e) {
100	      // Malformed assignments — fall back to YAML-only behavior silently

