 3	/**
 4	 * personas/plugins/ledger/frontmatter-templates.js
 5	 *
 6	 * Ledger-suite frontmatter template strings, ported from
 7	 * src/plugins/ledger/frontmatter-templates.ts in persona-builder.
 8	 *
 9	 * Two templates are defined — one for each supported output target:
10	 *   - FRONTMATTER_LEDGER_VSCODE   → VS Code instruction files
11	 *   - FRONTMATTER_LEDGER_CC       → Claude Code instruction files
12	 *
13	 * Template variables ({{varName}}) and conditionals ({{#if flag}}...{{/if}})
14	 * are resolved by the library's template engine at build time.
15	 */
16	
17	// ---------------------------------------------------------------------------
18	// Shared CC fields helper (inlined constant)
19	// ---------------------------------------------------------------------------
20	
21	/**
22	 * Shared Claude Code frontmatter fields used by the ledger CC template.
23	 *
24	 * Mirrors the return value of ccFrontmatterFields() from build-personas.js.
25	 */
26	const CC_FRONTMATTER_FIELDS =
27	  `permissionMode: {{cc_permission_mode}}
28	model: '{{cc_model}}'
29	memory: {{cc_memory}}`;
30	
31	// ---------------------------------------------------------------------------
32	// Ledger frontmatter templates
33	// ---------------------------------------------------------------------------
34	
35	/**
36	 * VS Code frontmatter template for the ledger persona suite.
37	 *
38	 * The `model` field is conditional: when the resolved model is the
39	 * "inherit" sentinel (i.e. `model` is falsy in the build context), the
40	 * field is omitted entirely so VS Code inherits from user settings.
41	 * Claude Code templates always render their `model:` line — see
42	 * FRONTMATTER_LEDGER_CC / CC_FRONTMATTER_FIELDS below.
43	 *
44	 * Used when target === 'vscode' and suite === 'ledger'.
45	 */
46	const FRONTMATTER_LEDGER_VSCODE = `---
47	id: {{id}}
48	name: '{{number}} - {{role}} v{{version}}'
49	description: 'Step {{number}}/{{total}} in the agent workflow.'
50	{{#if model}}model: '{{model}}'
51	{{/if}}role: {{role}}
52	author: {{author}}
53	version: {{version}}
54	{{#if last_updated}}
55	last_updated: {{last_updated}}
56	{{/if}}
57	vs_file_name: {{vs_file_name}}
58	tools: {{tools_json}}
59	---`;
60	
61	/**
62	 * Claude Code frontmatter template for the ledger persona suite.
63	 *
64	 * The mcpServers block is conditionally included — it appears only when
65	 * the has_mcp context variable is truthy.
66	 *
67	 * Used when target === 'claude-code' and suite === 'ledger'.
68	 */
69	const FRONTMATTER_LEDGER_CC = `---
70	name: {{cc_name}}
71	description: '{{cc_description}}'
72	role: {{role}}
73	author: {{author}}
74	version: {{version}}
75	{{#if last_updated}}
76	last_updated: {{last_updated}}
77	{{/if}}
78	tools: {{cc_tools_json}}
79	${CC_FRONTMATTER_FIELDS}
80	{{#if has_mcp}}
81	mcpServers:
82	  - {{mcp_server_name}}
83	{{/if}}
84	---`;
85	
86	module.exports = { FRONTMATTER_LEDGER_VSCODE, FRONTMATTER_LEDGER_CC };

101	    }
102	  }
