115	/**
116	 * Create a ledger persona build plugin.
117	 *
118	 * The returned object satisfies the PersonaBuildPlugin interface and can be
119	 * passed directly to the plugins array in a BuildConfig.
120	 *
121	 * @param {{ manifestRoles?: string[], warnOnUnknownRole?: boolean, registryDir?: string }} [options]
122	 *   Configuration options for the plugin.
123	 *
124	 *   - manifestRoles     List of canonical role names from the workflow manifest.
125	 *                       When omitted (or empty), role validation is skipped.
126	 *   - warnOnUnknownRole When true (default), unknown role → warning severity.
127	 *                       When false, unknown role → error severity.
128	 *   - registryDir       Absolute path to an alternate model-registry directory.
129	 *                       When provided, overrides the default registry loaded at
130	 *                       module-load time.  Intended for tests only.
131	 *
132	 * @returns {object} A fully configured PersonaBuildPlugin for the ledger suite
133	 */
134	function ledgerPlugin(options) {
135	  const { manifestRoles = [], warnOnUnknownRole = true, registryDir } = options || {};
136	
137	  // Use the injected registry when provided (test overrides); otherwise use the
138	  // module-level cached registry loaded from MODEL_REGISTRY_DIR.
139	  const { uuidToSlug: _uuidToSlug, slugToEntry: _slugToEntry, assignments: _assignments } =
140	    registryDir ? loadModelRegistry(registryDir) : _defaultRegistry;
141	
142	  /**
143	   * Per-persona rendered output cache.
144	   *
145	   * Populated by onPostRender and consumed by onValidate.
146	   * Keyed by composite key `${persona.name}:${target}` so that multi-target
147	   * builds correctly cache and validate per-target output independently.
148	   * onValidate immediately follows onPostRender in the per-persona pipeline.
149	   */
150	  const renderedOutputCache = new Map();
151	
152	  const plugin = {
153	    name: 'ledger',
154	
155	    // -------------------------------------------------------------------------
156	    // onSuiteInit — scope frontmatter templates to the ledger suite only
157	    // -------------------------------------------------------------------------
158	
159	    onSuiteInit(suite, _sharedMeta) {
160	      // Only apply ledger frontmatter when building the numbered (ledger) suite.
161	      // For other suites (e.g. standalone), remove the templates so the config-
162	      // level or library-default templates take effect instead.
163	      if (suite.personaMode === 'numbered') {
164	        plugin.frontmatterTemplates = {
165	          vscode: FRONTMATTER_LEDGER_VSCODE,
166	          'claude-code': FRONTMATTER_LEDGER_CC,
167	        };
168	      } else {
169	        delete plugin.frontmatterTemplates;
170	      }
171	    },
172	
173	    // -------------------------------------------------------------------------
174	    // onBuildContext — inject computed variables for template rendering
175	    // -------------------------------------------------------------------------
176	
177	    onBuildContext(context, persona, _suite) {
178	      const updated = Object.assign({}, context);
179	
180	      // --- model assignment override (assignments.json > YAML > _shared.yaml) --
181	      //
182	      // Priority chain (mirrors the name-mapping pass in build-personas.js):
183	      //   1. assignments.json persona_models[persona_id] → UUID → slug
184	      //      Skip when resolved slug === "inherit" (fall through to next level)
185	      //   2. per-persona YAML model / model_slug (already in context from YAML merge)
186	      //      Skip when model_slug === "inherit"
187	      //   3. assignments.json default_model_uuid → UUID → slug
188	      //      Skip when resolved slug === "inherit"
189	      //   4. _shared.yaml default_model / default_model_slug (already in context)
190	      //   5. "inherit" sentinel (model left falsy, cc_model set to "inherit")
191	      //
192	      // When a non-inherit slug is resolved:
193	      //   - updated['model']      ← entry.name (human-readable) or slug
194	      //   - updated['model_slug'] ← resolved slug
195	      //   - updated['cc_model']   ← entry.cc_model (from registry) or 'inherit'
196	      //
197	      // When the inherit sentinel applies, `model` is set to '' (falsy) so the
198	      // {{#if model}} conditional in the VS Code frontmatter template omits the
199	      // field entirely.  cc_model is set to 'inherit'.
200	
201	      const personaId = persona['id'] || updated['id'];
202	
203	      /**
204	       * Resolve model fields from a slug.
205	       * @param {string} slug
206	       * @returns {{ model: string, model_slug: string, cc_model: string }}
207	       */
208	      function resolveFromSlug(slug) {
209	        const entry = _slugToEntry.get(slug) || null;
210	        return {
211	          model:      entry ? entry.name : slug,
212	          model_slug: slug,
213	          cc_model:   (entry && entry.cc_model) ? entry.cc_model : 'inherit',
214	        };
215	      }
216	
217	      let resolved = null;
218	
219	      // Step 1: per-persona assignment
220	      if (_assignments && _assignments.persona_models && personaId) {
221	        const uuid = _assignments.persona_models[personaId];
222	        if (uuid) {
223	          const slug = _uuidToSlug.get(uuid);
224	          if (slug && slug !== 'inherit') {
225	            resolved = resolveFromSlug(slug);
226	          }
227	          // slug === 'inherit' → skip, fall through
228	        }
229	      }
230	
231	      // Step 2: per-persona YAML model_slug (already merged into context)
232	      if (!resolved) {
233	        const yamlSlug = updated['model_slug'];
234	        if (yamlSlug && yamlSlug !== 'inherit') {
235	          resolved = resolveFromSlug(yamlSlug);
236	        }
237	      }
238	
239	      // Step 3: assignments default_model_uuid
240	      if (!resolved && _assignments && _assignments.default_model_uuid) {
241	        const slug = _uuidToSlug.get(_assignments.default_model_uuid);
242	        if (slug && slug !== 'inherit') {
243	          resolved = resolveFromSlug(slug);
244	        }
245	        // slug === 'inherit' → skip, fall through
246	      }
247	
248	      // Step 4: _shared.yaml default_model_slug (already merged into context as default_model_slug)
249	      if (!resolved) {
250	        const sharedSlug = updated['default_model_slug'];
251	        if (sharedSlug && sharedSlug !== 'inherit') {
252	          // Use existing default_model name if available
253	          const entry     = _slugToEntry.get(sharedSlug) || null;
254	          const modelName = entry
255	            ? entry.name
256	            : (updated['default_model'] || sharedSlug);
257	          resolved = {
258	            model:      modelName,
259	            model_slug: sharedSlug,
260	            cc_model:   (entry && entry.cc_model) ? entry.cc_model : (updated['cc_model'] || 'inherit'),
261	          };
262	        }
263	      }
264	
265	      // Step 5: inherit sentinel fallback
266	      if (!resolved) {
267	        resolved = { model: '', model_slug: 'inherit', cc_model: 'inherit' };
268	      }
269	
270	      // Apply resolved values — only override when the registry/assignment
271	      // chain produced a result (resolved is always set at this point).
272	      updated['model']      = resolved.model;       // falsy ('') → {{#if model}} omits VS Code field
273	      updated['model_slug'] = resolved.model_slug;
274	      updated['cc_model']   = resolved.cc_model;
275	
276	      // --- roster_rendered ---------------------------------------------------
277	      // Roster lives in _shared.yaml → merged context (not per-persona YAML).
278	      const roster = updated['roster'];
279	      const personaNumber = updated['number'];
280	
281	      if (Array.isArray(roster) && personaNumber !== undefined) {
282	        updated['roster_rendered'] = renderRoster(roster, personaNumber);
283	      } else {
284	        updated['roster_rendered'] = '';
285	      }
286	
287	      // --- total (persona count in the suite) --------------------------------
288	      if (Array.isArray(roster) && !updated['total']) {
289	        updated['total'] = roster.length;
290	      }
291	
292	      // --- cc_name (Claude Code identifier) — alias for cc_file_name_stem ----
293	      if (!updated['cc_name'] && updated['cc_file_name_stem']) {
294	        updated['cc_name'] = updated['cc_file_name_stem'];
295	      }
296	
297	      // --- cc_description (Claude Code description) --------------------------
298	      // For ledger personas: derive from roster entry matching persona's number.
299	      // For standalone: fall back to the persona's description field.
300	      if (!updated['cc_description']) {

301	        if (Array.isArray(roster) && personaNumber !== undefined) {
302	          const entry = roster.find(r => r.number === personaNumber);
303	          if (entry) {
304	            updated['cc_description'] = entry.title + ' \u2014 ' + entry.short;
305	          }
306	        }
307	        // Fall back to the persona's description field (works for standalone)
308	        if (!updated['cc_description'] && updated['description']) {
309	          updated['cc_description'] = updated['description'];
310	        }
311	      }
312	
313	      // --- mcp_tools_table ---------------------------------------------------
314	      const mcpTools = persona['mcp_tools'];
315	
316	      if (Array.isArray(mcpTools)) {
317	        updated['mcp_tools_table'] = renderMcpToolsTable(mcpTools);
318	      } else {
319	        updated['mcp_tools_table'] = '';
320	      }
321	
322	      return updated;
323	    },
324	
325	    // -------------------------------------------------------------------------
326	    // onPostRender — capture rendered output for note_only guard in onValidate
327	    // -------------------------------------------------------------------------
328	
329	    onPostRender(output, persona, target) {
330	      // Cache the rendered output so onValidate can run the note_only guard.
331	      // Use a composite key so per-target outputs are cached independently.
332	      renderedOutputCache.set(`${persona.name}:${target}`, output);
333	      return output;
334	    },
335	
336	    // -------------------------------------------------------------------------
337	    // onValidate — role validation + note_only guard
338	    // -------------------------------------------------------------------------
339	
340	    onValidate(persona, _suite, target) {
341	      const results = [];
342	
343	      // 1. Role validation against the workflow manifest
344	      const role = persona['role'];
345	      const roleResults = validateRole(role, manifestRoles).map((r) => ({
346	        ...r,
347	        // When warnOnUnknownRole is false, escalate warning → error so that
348	        // unknown roles are treated as hard failures rather than advisories.
349	        severity: (r.severity === 'warning' && !warnOnUnknownRole)
350	          ? 'error'
351	          : r.severity,
352	      }));
353	      results.push(...roleResults);
354	
355	      // 2. note_only guard — verify internal-only MCP tools are not in the output.
356	      // Use the composite key matching the one written by onPostRender; fall back
357	      // to 'unknown' when target is absent (e.g. in unit-test contexts).
358	      const mcpTools = persona['mcp_tools'];
359	      const cacheKey = `${persona.name}:${target !== undefined ? target : 'unknown'}`;
360	      const renderedOutput = renderedOutputCache.get(cacheKey) || '';
361	      results.push(...validateNoteOnlyGuard(renderedOutput, mcpTools));
362	
363	      return results;
364	    },
365	
366	    // -------------------------------------------------------------------------
367	    // frontmatterTemplates — set dynamically by onSuiteInit (not static)
368	    // -------------------------------------------------------------------------
369	    // The frontmatterTemplates property is set/removed by onSuiteInit so that
370	    // ledger templates only apply when building the ledger (numbered) suite.
371	    // For standalone builds, the property is deleted so that config-level or
372	    // library-default templates take effect instead.
373	  };
374	
375	  return plugin;
376	}
