 87	/**
 88	 * Resolve display name, slug, and cc_model for a persona.
 89	 *
 90	 * Priority chain (mirrors the build plugin + orchestrator):
 91	 *   1. assignments.json persona_models[personaId]  (skip if resolved slug === "inherit")
 92	 *   2. yamlModelSlug                               (skip if value === "inherit")
 93	 *   3. assignments.json default_model_uuid          (skip if resolved slug === "inherit")
 94	 *   4. sharedModelSlug / sharedModelName
 95	 *   5. "inherit" sentinel — { model: "Inherit / Auto", model_slug: "inherit", cc_model: "inherit" }
 96	 *
 97	 * @param {string|undefined}       personaId       Persona ID (used as assignments key).
 98	 * @param {string|undefined}       yamlModelSlug   Per-persona model_slug from YAML.
 99	 * @param {string|undefined}       sharedModelSlug Shared default model slug (_shared.yaml).
100	 * @param {string|undefined}       sharedModelName Shared default model name (_shared.yaml).

101	 * @param {Map<string,string>}     uuidToSlug      UUID → slug from registry.
102	 * @param {object|null}            assignments     Parsed assignments.json (or null).
103	 * @param {object[]}               registryEntries Array of { id, name, slug, cc_model } registry entries.
104	 * @returns {{ model: string, model_slug: string, cc_model: string }}
105	 */
106	export function resolveModel(
