134	        return {
135	          model:      entry ? entry.name : slug,
136	          model_slug: slug,
137	          cc_model:   entry ? entry.cc_model : 'inherit',
138	        };
139	      }
140	      // slug === 'inherit' → skip, fall through
141	    }
142	  }
143	
144	  // 2. Per-persona YAML model_slug
