152	  }
153	
154	  // 3. Default assignment from assignments.json
155	  if (assignments && assignments.default_model_uuid) {
156	    const slug = uuidToSlug.get(assignments.default_model_uuid);
157	    if (slug && slug !== 'inherit') {
